<script setup lang="ts">
import {workspaceFor} from '~/shared/cms/workflow.mjs'
definePageMeta({layout:'admin'})
const {api,message}=useCmsAdmin(),selected=ref<any>(null),error=ref(''),notice=ref(''),busy=ref(false),uploadInput=ref<HTMLInputElement>()
const baseline=ref('')
const {upload,uploading,progress,uploadError}=useCmsUpload()
const dirty=computed(()=>!!selected.value&&JSON.stringify(selected.value)!==baseline.value)
useCmsUnsaved(dirty)
function open(item:any){selected.value={...item};baseline.value=JSON.stringify(selected.value);error.value=''}
function close(){if(!busy.value&&(!dirty.value||window.confirm('檔案說明尚未儲存，確定關閉？')))selected.value=null}
async function uploadFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;notice.value='';const result=await upload(file);if(result)notice.value='檔案已上傳，可在修改內容時選用。';(event.target as HTMLInputElement).value=''}
async function save(archive=false){if(busy.value)return;if(archive&&!window.confirm('收起後將無法在修改內容時選用，確定收起這個檔案？'))return;error.value='';busy.value=true;try{await api('media',{method:'PATCH',body:{...selected.value,archived:archive}});selected.value=null;await refreshNuxtData('cms-media');notice.value=archive?'已收起這個檔案。':'檔案說明已儲存。'}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="cms-page"><div class="cms-heading"><div><h1>圖片與檔案</h1><p class="cms-muted">圖片最大 10MB，PDF 最大 30MB。</p></div><button class="cms-button cms-button-gold" :disabled="uploading" @click="uploadInput?.click()">{{ uploading?`上傳中 ${progress}%`:'上傳圖片或檔案' }}</button><input ref="uploadInput" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" class="cms-sr-only" aria-label="上傳圖片或檔案" @change="uploadFile" /></div><p v-if="uploadError||error&&!selected" class="cms-error" role="alert">{{ uploadError||error }}</p><p v-if="notice" class="cms-notice" role="status">{{ notice }}</p><AdminMediaGrid @select="open" /><AdminDialog :open="!!selected" title="圖片或檔案說明" @close="close"><form v-if="selected" class="cms-form" @submit.prevent="save()"><p v-if="error" class="cms-error" role="alert">{{ error }}</p><AdminImage v-if="selected.mime!=='application/pdf'" :src="selected.src" :alt="selected.alt||selected.name" /><label>檔案名稱<input v-model="selected.name" required maxlength="255" /></label><label>圖片說明<input v-model="selected.alt" maxlength="500" /><small class="cms-field-help">簡短描述圖片內容，幫助無法看見圖片的人理解。</small></label><label>分類<input v-model="selected.category" maxlength="80" /></label><details open><summary>使用位置（{{ selected.uses.length }}）</summary><ul><li v-for="(u,i) in selected.uses" :key="i">{{ workspaceFor(u.documentId)?.title||u.title }}</li></ul><p v-if="!selected.uses.length" class="cms-muted">目前沒有內容使用這份檔案。</p></details><p v-if="selected.uses.length" class="cms-field-help">目前內容或過去版本仍使用這份檔案，因此無法收起。</p><div class="cms-actions"><button type="button" class="cms-button" :disabled="busy||selected.uses.length>0" @click="save(true)">收起不用的檔案</button><button class="cms-button cms-button-gold" :disabled="busy">{{ busy?'儲存中…':'儲存說明' }}</button></div></form></AdminDialog></div></template>
